use lg_core::Money;
use lg_tax::{region, Line, RoundingScope};
use lg_tax::calc::breakdown;

#[test]
fn disc_l16() {
    let r = region("BR-PE").unwrap();
    let b = breakdown(&[Line::service("s", Money::of(100000, "BRL"))], r, RoundingScope::PerLine).unwrap();
    assert_eq!(b.tax.minor(), 5000);
    let g = breakdown(&[Line::goods("g", Money::of(100000, "BRL"))], r, RoundingScope::PerLine).unwrap();
    assert_eq!(g.tax.minor(), 20500);
}
